import threading
import time


class Counter:
    def __init__(self):
        self.n = 0

    def inc(self):
        v = self.n
        time.sleep(0.0001)
        self.n = v + 1

    def run(self, threads=8, loops=200):
        ts = []
        for _ in range(threads):
            t = threading.Thread(target=lambda: [Counter.inc(self) for _ in range(loops)])
            ts.append(t)
        for t in ts:
            t.start()
        for t in ts:
            t.join()
        return self.n


if __name__ == "__main__":
    print(Counter().run())
